"""Generate a two-page executive memo, four-page report and seven-slide walkthrough."""
import json,pathlib
from reportlab.pdfgen import canvas
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4,landscape
from ingest import ROOT

GREEN=colors.HexColor('#264F3B');INK=colors.HexColor('#263D31');MUTED=colors.HexColor('#7B8E77');LIGHT=colors.HexColor('#EDF3E8');LINE=colors.HexColor('#DDE6D6')
def money(v):return f'${v/1000:,.1f}B'
def pct(v):return f'{v*100:.1f}%'
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='Label',fontName='Helvetica-Bold',fontSize=8,leading=12,textColor=MUTED,spaceAfter=10))
styles.add(ParagraphStyle(name='TitleFL',fontName='Helvetica-Bold',fontSize=27,leading=31,textColor=INK,spaceAfter=13))
styles.add(ParagraphStyle(name='SubFL',fontName='Helvetica',fontSize=10,leading=15,textColor=MUTED,spaceAfter=18))
styles.add(ParagraphStyle(name='HeadingFL',fontName='Helvetica-Bold',fontSize=12,leading=16,textColor=GREEN,spaceBefore=15,spaceAfter=8))
styles.add(ParagraphStyle(name='BodyFL',fontName='Helvetica',fontSize=9.5,leading=14.5,textColor=INK,spaceAfter=9))
styles.add(ParagraphStyle(name='SmallFL',fontName='Helvetica',fontSize=7.5,leading=11,textColor=MUTED,spaceAfter=6))
def P(s,style='BodyFL'):return Paragraph(s,styles[style])
def T(rows,widths=None):
 t=Table([[P(str(x),'SmallFL') for x in r] for r in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),LIGHT),('TEXTCOLOR',(0,0),(-1,-1),INK),('LINEBELOW',(0,0),(-1,0),.5,LINE),('LINEBELOW',(0,1),(-1,-1),.4,LINE),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('VALIGN',(0,0),(-1,-1),'TOP')]))
 return t
def footer(c,d):
 w,h=d.pagesize;c.setStrokeColor(LINE);c.line(42,39,w-42,39);c.setFillColor(MUTED);c.setFont('Helvetica',7);c.drawString(42,26,'FINANCIAL LENS / MICROSOFT  |  Independent public-data analysis');c.drawRightString(w-42,26,f'{d.page:02d}');c.setFont('Helvetica',6);c.drawString(42,h-24,'RESEARCH SNAPSHOT / NOVEMBER 7, 2026')
def doc(path,story,pagesize=A4):SimpleDocTemplate(str(ROOT/path),pagesize=pagesize,rightMargin=42,leftMargin=42,topMargin=45,bottomMargin=54,title='Microsoft | Financial Lens',author='Independent portfolio project').build(story,onFirstPage=footer,onLaterPages=footer)

def memo(j):
 h=j['history'];r=h[-1];b=j['scenarios']['base'];lo=j['scenarios']['downside'];hi=j['scenarios']['upside'];d=j['drivers'];imp={x['x']:x['fcf'] for x in j['sensitivities'] if x['kind']=='driver_impact'}
 s=[P('EXECUTIVE RECOMMENDATION / 01','Label'),P('Fund growth with<br/>cash discipline.','TitleFL'),P('Microsoft Corporation | Annual financial forecasting &amp; performance analysis','SubFL'),P('The decision','HeadingFL'),P(f'Prioritize a stage-gated capital program and preserve distribution flexibility. FY2026 revenue grew {pct(r["revenue"]/h[-2]["revenue"]-1)}, but cash capex reached {pct(r["capex"]/r["revenue"])} of revenue and FCF fell {pct(1-r["fcf"]/h[-2]["fcf"])}. The base model implies FY2029 FCF of {money(b[-1]["fcf"])}, versus {money(lo[-1]["fcf"])} to {money(hi[-1]["fcf"])} under the defined operating scenarios. These are conditional estimates, not management guidance.'),T([['Headline evidence','FY2026 actual','FY2029 base forecast'],['Revenue',money(r['revenue']),money(b[-1]['revenue'])],['Operating margin',pct(r['ebit']/r['revenue']),pct(b[-1]['ebit']/b[-1]['revenue'])],['Cash capex',money(r['capex']),money(b[-1]['capex'])],['Free cash flow',money(r['fcf']),money(b[-1]['fcf'])]],[230,135,146]),P('Why this matters','HeadingFL'),P(f'Microsoft generated {money(r["cfo"])} of operating cash flow in FY2026, against {money(r["capex"])} of cash PP&amp;E spending. Finance lease additions of {money(r["lease_add"])} also expanded capacity and future obligations. Standard FCF (CFO minus cash capex) does not capture that entire capital commitment.'),P('The three levers','HeadingFL'),P(f'<b>Capital intensity:</b> one additional percentage point of capex / revenue reduces FY2027 FCF by {money(abs(imp["capex_rate"]))}. <b>Operating margin:</b> one percentage point of margin adds {money(imp["margin"])} after tax. <b>Collections:</b> one extra collection day consumes {money(abs(imp["dso"]))}. These are one-at-a-time model sensitivities with different shock sizes, not causal estimates.'),P('Read the forecast with its limits','HeadingFL'),P(f'The base uses {pct(d["growth"])} annual revenue growth (last two growth rates averaged), {pct(d["margin"])} operating margin (three-year mean), and {pct(d["capex_rate"])} capex intensity (latest year). Finance leases are modeled explicitly; other assets/liabilities stay fixed. The annual model does not use FY2027 interim results.'),P('Source: original Microsoft annual SEC filings FY2022–26. USD billions shown; model uses USD millions. All 165 selected historical facts reconcile to archived filing inline XBRL. Educational analysis, not investment advice.','SmallFL'),PageBreak(),P('EXECUTIVE RECOMMENDATION / 02','Label'),P('Actions, triggers<br/>and trade-offs.','TitleFL'),T([['FY2029 outcome','Downside','Base','Upside'],['Revenue',money(lo[-1]['revenue']),money(b[-1]['revenue']),money(hi[-1]['revenue'])],['FCF',money(lo[-1]['fcf']),money(b[-1]['fcf']),money(hi[-1]['fcf'])],['Ending cash',money(lo[-1]['cash']),money(b[-1]['cash']),money(hi[-1]['cash'])]],[190,107,107,107]),P('1 / Gate incremental capacity commitments','HeadingFL'),P(f'Review cash capex and new finance lease commitments together. Escalate review if cash capex exceeds the downside planning level of {pct(d["capex_rate"]+.02)} of revenue, or capacity utilization fails internal milestones. Monitor capex / revenue, lease additions, utilization and FCF after lease principal. Trade-off: slower deployment may constrain growth; no utilization dataset is available in this project.'),P('2 / Protect margin and collection cadence','HeadingFL'),P(f'Reassess the cost envelope if annual operating margin falls below the downside level of {pct(d["margin"]-.03)}, and investigate DSO above {(d["dso"]+5):.0f} days. Monitor margin, receivables aging and contract liabilities. The model suggests meaningful cash exposure, but annual DSO and DPO are blunt proxies; validate monthly operating evidence before acting.'),P('3 / Make distributions conditional on liquidity','HeadingFL'),P(f'The cash floor is FY2026 cash of {money(d["cash_floor"])}. The downside requires {money(sum(x["new_debt"] for x in lo))} of cumulative modeled borrowing over three years if dividend and buyback ratios remain fixed. Reduce discretionary repurchases before accepting avoidable borrowing, subject to actual treasury constraints. This is a policy recommendation; the model holds payout ratios fixed to expose the trade-off.'),P('Validation and uncertainty','HeadingFL'),P('Four one-year holdouts (FY2023–26) use original annual facts available at each origin filing date. Revenue MAPE is 4.6%, EBIT 8.0%, and FCF 18.4%. Model MAE is 12.0% lower than the prior-growth baseline for revenue and 18.6% lower for FCF, but 4.8% higher for EBIT. Every FCF holdout is overforecast. Four observations do not establish statistical skill; retrospective development has researcher hindsight risk.'),P('Methodology / scope','HeadingFL'),P('Snapshot: November 7, 2026. Latest modeled annual period: June 30, 2026. Forecast: FY2027–29. Aggregate, driver-based three-statement model; cash is a rollforward and explicit borrowing funds a minimum cash rule. Opening financing balances determine interest. No segment forecast, debt maturity schedule, acquisitions, new operating leases, deferred-tax forecast or securities sales. Depreciation and interest are proxies. Source files, assumptions, checks and backtests are included.','SmallFL')]
 doc('docs/executive_memo.pdf',s)

def report(j):
 h=j['history'];b=j['scenarios']['base'];r=h[-1];s=[]
 s += [P('FINANCIAL REPORT / 01','Label'),P('Performance in perspective.','TitleFL'),P('Microsoft | Five annual actuals and a three-year base forecast','SubFL')]
 s+=[T([['USD billions',*[f'FY{x["year"]}{"F" if x.get("forecast") else "A"}' for x in h+b]],*[[label,*[f'{x[k]/1000:,.1f}' for x in h+b]] for label,k in [('Revenue','revenue'),('Operating profit','ebit'),('Net income','net_income'),('CFO','cfo'),('Cash capex','capex'),('FCF','fcf'),('Cash','cash')]]],[120]+[48.9]*8),P('Cash is the management lens','HeadingFL'),P(f'FY2026 revenue was {money(r["revenue"])}, while cash capex was {money(r["capex"])} and FCF was {money(r["fcf"])}. FY2029 base FCF is {money(b[-1]["fcf"])}. A = reported; F = modeled. FCF = CFO minus cash capex. Financing leases are separate.'),P('Sources / original Microsoft 10-K filings and SEC companyfacts. All values USD billions. Fiscal year ends June 30.','SmallFL'),PageBreak()]
 s += [P('DRIVER ANALYSIS / 02','Label'),P('Growth has a capital cost.','TitleFL'),T([['Ratio / year',*[f'FY{x["year"]}A' for x in h]],*[[label,*[fn(x) for x in h]] for label,fn in [('Gross margin',lambda x:pct(x['gross_profit']/x['revenue'])),('Operating margin',lambda x:pct(x['ebit']/x['revenue'])),('Cash capex / revenue',lambda x:pct(x['capex']/x['revenue'])),('CFO / revenue',lambda x:pct(x['cfo']/x['revenue'])),('DSO (days)',lambda x:f'{x["ar"]/x["revenue"]*365:.1f}'),('DPO (days)',lambda x:f'{x["ap"]/x["cogs"]*365:.1f}')]]],[160]+[70.2]*5),P('FY2027 local cash sensitivities','HeadingFL'),T([['Driver shock','FCF change'],*[[{'growth':'+1 percentage point growth','margin':'+1 percentage point margin','capex_rate':'+1 percentage point capex','dso':'+1 collection day'}[x['x']],money(x['fcf'])] for x in j['sensitivities'] if x['kind']=='driver_impact']],[360,151]),P('DSO = AR / revenue × 365; DPO = AP / COGS × 365. Annual balance proxies can be distorted by construction payables. Sensitivities vary one driver at a time from the base and are not causal estimates.','SmallFL'),PageBreak()]
 s += [P('SCENARIOS / 03','Label'),P('A range, not a promise.','TitleFL'),T([['FY2029 forecast','Downside','Base','Upside'],*[[label,*[money(j['scenarios'][s][-1][k]) for s in ['downside','base','upside']]] for label,k in [('Revenue','revenue'),('Operating income','ebit'),('FCF','fcf'),('Cash','cash'),('Long-term debt','debt'),('Finance lease liability','lease')]]],[190,107,107,107]),P('Scenario design','HeadingFL'),P('Base: historical anchors held constant. Upside: +3 percentage points growth, +2 points operating margin, 3 fewer collection days, 2 points lower cash capex. Downside: 5 points lower growth, 3 points lower margin, 5 extra collection days, 2 points higher capex. The shock ranges are analyst judgments.'),P('Liquidity rule','HeadingFL'),P(f'Minimum cash is {money(j["drivers"]["cash_floor"])}. Explicit new borrowing covers a shortfall. Interest uses opening long-term debt plus finance leases. Existing long-term principal is held fixed. Other assets, including marketable securities, are held fixed.'),P('Two sensitivity grids','HeadingFL'),P('The Excel model and dashboard include FY2027 revenue growth × operating margin and DSO × capex matrices. The workbook also shows EBIT and net income in the growth × margin grid. The scenario controls recalculate the three statements.'),PageBreak()]
 s += [P('ACCURACY & RISKS / 04','Label'),P('Show the error, too.','TitleFL'),T([['Metric / n = 4','MAE ($B)','MAPE','Bias ($B)','Baseline MAE ($B)'],*[[x['metric'].upper(),f'{x["mae"]/1000:.1f}',pct(x['mape']),f'{x["bias"]/1000:.1f}',f'{x["baseline_mae"]/1000:.1f}'] for x in j['backtest_summary']]],[150,85,85,85,106]),P('Backtest protocol','HeadingFL'),P(j['protocol']),P('What failed','HeadingFL'),P('The model underperforms the baseline for EBIT. Every FCF prediction is above actual. A small retrospective sample cannot demonstrate robust forecasting skill. No parameter was optimized on the holdout errors during this implementation.'),P('Assurance','HeadingFL'),P(f'{len(j["checks"])} core checks passed: accounting identities, cash-flow consistency, forecast linkage, scenario order and date controls. Separately, 165 original annual source facts reconcile. The workbook formula evaluator and stress tests add implementation assurance; none establishes that future assumptions will occur.'),P('Limits','HeadingFL'),P('Annual aggregate scope; no FY2027 interim inputs, segment forecast, detailed asset-cohort schedule, maturity schedule, acquisitions, new operating leases or deferred-tax projection. Other assets and liabilities fixed. Forecasts are conditional educational analysis. Not investment advice.'),P('Reviewer path / source manifest → raw original filings → assumptions → workbook formulas → backtest errors → memo. Native Power BI .pbix is not included; CSVs and import guidance are provided.','SmallFL')]
 doc('dashboards/financial_report.pdf',s,pagesize=landscape(A4))

def slides(j):
 b=j['scenarios']['base'][-1];lo=j['scenarios']['downside'][-1];hi=j['scenarios']['upside'][-1];r=j['history'][-1]
 slides=[('01 / THE MANAGEMENT QUESTION','Can growth fund its own capital needs?',['Microsoft · FY2022–26 reported history · FY2027–29 forecast','A reusable, evidence-based financial modeling case study','Annual planning assumptions; not company guidance or investment advice']),('02 / THE HISTORICAL PICTURE','Revenue growth is only half the story.',[f'FY2026 revenue: {money(r["revenue"])} · operating income: {money(r["ebit"])}',f'Cash capex: {money(r["capex"])} · FCF: {money(r["fcf"])}','Capital spending has become the key constraint to monitor.']),('03 / THE FINANCIAL ENGINE','One model. Three linked statements.',['Revenue and margins → net income → cash flow and equity','Working capital, PP&E and finance leases drive the balance sheet','A stated cash floor triggers borrowing. Opening balances determine interest.']),('04 / THE THREE-YEAR OUTLOOK','Make the assumptions reviewable.',[f'Base growth: {pct(j["drivers"]["growth"])} · margin: {pct(j["drivers"]["margin"])}',f'FY2029 base revenue: {money(b["revenue"])} · FCF: {money(b["fcf"])}',f'FY2029 FCF range: {money(lo["fcf"])} downside to {money(hi["fcf"])} upside']),('05 / CHALLENGE THE FORECAST','Four holdouts. Mixed evidence.',['Revenue MAPE: 4.6% · EBIT: 8.0% · FCF: 18.4%','Revenue / FCF MAE beat the prior-growth baseline; EBIT does worse.','Every FCF holdout overforecasts. Four origins cannot establish skill.']),('06 / THE RECOMMENDATION','Protect growth through cash discipline.',['Gate incremental cash and lease capital commitments.','Monitor operating margin, collections and capital utilization.','Make discretionary buybacks conditional on liquidity needs.']),('07 / REVIEW & REPRODUCE','Trace every step back to evidence.',['165 annual facts reconciled to archived 10-K inline XBRL.','48 core model checks, stress tests and Excel formula evaluation.','Open README, edit the workbook, explore the dashboard, rerun Python.'])]
 path=ROOT/'docs/executive_walkthrough.pdf';c=canvas.Canvas(str(path),pagesize=(960,540));c.setTitle('Microsoft | Executive walkthrough')
 for index,(eyebrow,h,bullets) in enumerate(slides):
  c.setFillColor(colors.HexColor('#F6F8F2'));c.rect(0,0,960,540,fill=1,stroke=0);c.setFillColor(GREEN);c.setFont('Helvetica-Bold',10);c.drawString(58,482,eyebrow);c.setFont('Helvetica-Bold',34)
  text=Paragraph(h,ParagraphStyle('SlideTitle',fontName='Helvetica-Bold',fontSize=34,leading=41,textColor=INK));text.wrap(830,130);text.drawOn(c,58,352)
  y=281
  for line in bullets:
   p=Paragraph(line,ParagraphStyle('SlideBody',fontName='Helvetica',fontSize=17,leading=25,textColor=MUTED));_,height=p.wrap(800,100);c.setFillColor(GREEN);c.circle(62,y+6,2,fill=1,stroke=0);p.drawOn(c,80,y-height+20);y-=height+31
  c.setStrokeColor(LINE);c.line(58,55,902,55);c.setFont('Helvetica',8);c.setFillColor(MUTED);c.drawString(58,37,'FINANCIAL LENS / MICROSOFT  |  Independent public-data analysis  |  November 7, 2026');c.drawRightString(902,37,f'{index+1:02d} / 07');c.showPage()
 c.save()

if __name__=='__main__':
 j=json.loads((ROOT/'data/processed/model.json').read_text());memo(j);report(j);slides(j);print('Created memo, report and walkthrough PDFs')
